using Utsav.Domain.Finance;

namespace Utsav.UnitTests.Finance;

/// <summary>
/// Parity tests for the port of server/paymentMode.mjs. The expectations here
/// were generated by running the original JS regex over the same inputs
/// (see tests/parity/payment-mode-oracle.mjs), not by reading the code.
/// </summary>
public class PaymentModeClassifierTests
{
    // The five payment_mode labels seeded by seedReferenceData().
    [Theory]
    [InlineData("Cash", FundSideKind.Cash)]
    [InlineData("Online - Gpay", FundSideKind.Bank)]
    [InlineData("Cheque", FundSideKind.Bank)]
    [InlineData("Bank Transfer", FundSideKind.Bank)]
    [InlineData("Pending", FundSideKind.Cash)]
    public void Classifies_the_seeded_lookup_labels(string mode, FundSideKind expected) =>
        Assert.Equal(expected, PaymentModeClassifier.BucketOf(mode));

    // Modes a committee might add later — the reason the classifier matches
    // words rather than exact labels.
    [Theory]
    [InlineData("UPI")]
    [InlineData("PhonePe")]
    [InlineData("Paytm")]
    [InlineData("BHIM")]
    [InlineData("GPay")]
    [InlineData("G-Pay")]
    [InlineData("G Pay")]
    [InlineData("NEFT")]
    [InlineData("IMPS")]
    [InlineData("RTGS")]
    [InlineData("Net Banking")]
    [InlineData("net-banking")]
    [InlineData("Demand Draft")]
    [InlineData("DD")]
    [InlineData("Debit Card")]
    [InlineData("Credit Card")]
    [InlineData("Online")]
    [InlineData("check")]
    public void Recognises_online_modes_added_later(string mode) =>
        Assert.Equal(FundSideKind.Bank, PaymentModeClassifier.BucketOf(mode));

    /// <summary>
    /// The deliberate default: blank/unknown is cash, because the overwhelming
    /// majority of historical rows have no mode recorded and the money was in
    /// the tin. Changing this silently moves lakhs between the two balances.
    /// </summary>
    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("   ")]
    [InlineData("Cash")]
    [InlineData("cash in hand")]
    [InlineData("Pending")]
    [InlineData("hand delivered")]
    [InlineData("collected by Pranab")]
    public void Unknown_or_blank_counts_as_cash(string? mode) =>
        Assert.Equal(FundSideKind.Cash, PaymentModeClassifier.BucketOf(mode));

    [Fact]
    public void Matching_is_case_insensitive()
    {
        Assert.Equal(FundSideKind.Bank, PaymentModeClassifier.BucketOf("BANK TRANSFER"));
        Assert.Equal(FundSideKind.Bank, PaymentModeClassifier.BucketOf("bank transfer"));
        Assert.Equal(FundSideKind.Bank, PaymentModeClassifier.BucketOf("BaNk TrAnSfEr"));
    }

    /// <summary>
    /// The pattern is a substring match, exactly as the JS original is — a
    /// documented quirk worth pinning so a "tightening" refactor is caught.
    /// "Cashcard" contains "card", so it banks.
    /// </summary>
    [Fact]
    public void Substring_matching_is_intentional()
    {
        Assert.True(PaymentModeClassifier.IsOnline("Cashcard"));
        Assert.True(PaymentModeClassifier.IsOnline("transferred by hand"));
    }
}
